// Account defines model for Account.
type Account struct {
	CreatedAt time.Time       `json:"created_at"`
	DraftPass *DraftPassState `json:"draft_pass"`
	Email     string          `json:"email"`
	Features  []Feature       `json:"features"`
	FirstName *string         `json:"first_name"`

	// Format the context's format, the board every page opens in: the selected league's, else the format chosen with no league, null when neither
	Format *BoardFormat `json:"format"`

	// Handle the name shown in lobbies, 3 to 20 letters, digits or underscores, not starting with a digit
	Handle   *string            `json:"handle"`
	Id       openapi_types.UUID `json:"id"`
	LastName *string            `json:"last_name"`

	// League the selected league, the site's context; with no selection made, the newest followed league; null when the account follows none or chose a format alone
	League *ContextLeague `json:"league"`

	// Leagues every league the account follows, newest first, as the shell's switcher lists them
	Leagues    []ContextLeague  `json:"leagues"`
	Membership *MembershipState `json:"membership"`

	// Season the NFL season the site is in, for a visitor with no league, from the kickoffs the API reads
	Season SiteSeason `json:"season"`
}

// AccountUpdate defines model for AccountUpdate.
type AccountUpdate struct {
	Handle string `json:"handle"`
}

// AttachInput defines model for AttachInput.
type AttachInput struct {
	// Host the host a league runs on, named as a mechanism
	Host *LeagueHost `json:"host,omitempty"`

	// Link the league link as pasted
	Link string `json:"link"`

	// Me exactly one of username (Sleeper only) and roster_id
	Me AttachSeat `json:"me"`
}

// AttachPreview defines model for AttachPreview.
type AttachPreview struct {
	// Host the host a league runs on, named as a mechanism
	Host         LeagueHost `json:"host"`
	HostLeagueId string     `json:"host_league_id"`
	Name         string     `json:"name"`

	// Season the league's season
	Season int `json:"season"`

	// SeatByUsername whether the host finds a seat by username (Sleeper does)
	SeatByUsername bool         `json:"seat_by_username"`
	Teams          []LeagueTeam `json:"teams"`
}

// AttachPreviewInput defines model for AttachPreviewInput.
type AttachPreviewInput struct {
	// Host the host a league runs on, named as a mechanism
	Host *LeagueHost `json:"host,omitempty"`

	// Link the league link as pasted
	Link string `json:"link"`
}

// AttachSeat exactly one of username (Sleeper only) and roster_id
type AttachSeat struct {
	RosterId *int    `json:"roster_id,omitempty"`
	Username *string `json:"username,omitempty"`
}

// AttachedLeague defines model for AttachedLeague.
type AttachedLeague struct {
	AttachedAt time.Time `json:"attached_at"`

	// DraftAt the host's draft time, null when the host does not say
	DraftAt *time.Time `json:"draft_at"`

	// Host the host a league runs on, named as a mechanism
	Host         LeagueHost         `json:"host"`
	HostLeagueId string             `json:"host_league_id"`
	Id           openapi_types.UUID `json:"id"`

	// LastReadAt the league's last host read for this account, null when never read
	LastReadAt *time.Time `json:"last_read_at"`

	// Name the league's name at its last read
	Name string `json:"name"`

	// Phase where a followed league is in its season, computed at read time from the host's facts: pre_draft before its draft, draft_day when the draft starts within 24 hours or is under way, in_season from the draft to the playoffs (a drafted league the host gives no current week is in_season while the site season is preseason), playoffs from the league's playoff start week until the host says the season is over, offseason after it (or a drafted league with no current week once the NFL regular season has ended)
	Phase LeaguePhase `json:"phase"`

	// PhaseBasis one sentence naming the fact the phase came from, in the site's words
	PhaseBasis string `json:"phase_basis"`

	// PlayoffStartWeek the league's first playoff week as the host states it, null when the host does not say
	PlayoffStartWeek *int `json:"playoff_start_week"`
	RosterId         int  `json:"roster_id"`
	Season           int  `json:"season"`

	// Standing the drafter's record and place at the last read, null when unread
	Standing *LeagueStanding `json:"standing"`

	// TeamName the drafter's team at the last read, empty when unread
	TeamName string `json:"team_name"`

	// WaiversOpen the host still runs waivers this week: false in and after the playoffs where the host closes them, and once the season is over, else true
	WaiversOpen bool `json:"waivers_open"`
}

// BoardFormat defines model for BoardFormat.
type BoardFormat string

// BoardPlayer one player of the board a room drafts from
type BoardPlayer struct {
	// Adp where drafters take him
	Adp *float64 `json:"adp"`
	Bye *int     `json:"bye"`

	// Gap drafters' ADP less his place on our board (the pool's order by points over replacement), the ADP the column prints less the place, a tenth: plus when drafters take him later than we rank him; null with no ADP or no place (a kicker, a defense). Absent from a server older than the column
	Gap      *float64 `json:"gap,omitempty"`
	Headshot string   `json:"headshot"`
	Id       string   `json:"id"`
	Name     string   `json:"name"`

	// Points projected season points
	Points       *float64       `json:"points"`
	Position     PlayerPosition `json:"position"`
	PositionRank int            `json:"position_rank"`

	// Status his injury designation on the newest hourly capture (GET /boards/{format} only), absent when the capture does not list him
	Status *BoardStatus `json:"status,omitempty"`
	Team   string       `json:"team"`

	// Vor points over replacement for this league
	Vor *float64 `json:"vor"`
}

// BoardStatus his injury designation on the newest hourly capture (GET /boards/{format} only), absent when the capture does not list him
type BoardStatus struct {
	// AsOf the stamp of the capture that lists him
	AsOf time.Time `json:"as_of"`

	// SeasonLong injured reserve, suspended, PUP, NFI, or out with the capture's note saying out for the season: his rest-of-season figure assumes he plays, so he is placed below every available player at his position. A week's out, doubtful or questionable moves nothing
	SeasonLong bool `json:"season_long"`

	// Since the first capture of his unbroken run under a season-long status; null for a week's designation and for a run older than the captures read, whose start we do not know
	Since *time.Time `json:"since"`

	// Source the capture's feed in the research store: tank01_injuries_by_date
	Source string            `json:"source"`
	Status DesignationStatus `json:"status"`
}

